  if number>=220 and not gates: missing.append(p.name)
  for gate in gates:
   # Each fenced command group is an independent gate; historical prose is excluded.
   commands=re.findall(r'```(?:bash|sh|shell)?\n(.*?)```',gate,re.S)
   if not commands: commands=[gate]
   for command in commands:
    cuda=bool(re.search(r'--linux-cuda|linux-cuda\.sh|-fcuda',command))
